by={i['id']:i for i in items}; kids=collections.defaultdict(list)
for i in items:
    p=i.get('parent') or ''
    if p: kids[p].append(i)
bad=0
for pid,ch in sorted(kids.items()):
    p=by.get(pid)
    if not p: continue
    if p['status'] in OPEN and all(c['status'] in CLOSED for c in ch):
        print('MISMATCH parent-open/kids-closed:',pid,p['status']); bad+=1
