print('statuses:',dict(collections.Counter(i['status'] for i in items)))
print('c9 subtree:')
for i in items:
    if 'c9-chartlocus' in i['id']: print('  ',i['id'],'|',i['status'])
for w in d.get('warnings') or []: print('WARN:',w)
